require_once dirname(__DIR__,3).'/app/bootstrap.php';require_login();header('Cache-Control: private, no-store, max-age=0');api_rate_limit('v1-map',60,60);$category=trim((string)($_GET['category']??''));$where=["status='published'",'latitude IS NOT NULL','longitude IS NOT NULL'];$params=[];if($category!==''&&in_array($category,categories(),true)){$where[]='category=:c';$params[':c']=$category;}$s=db()->prepare('SELECT * FROM listings WHERE '.implode(' AND ',$where).' ORDER BY featured DESC,name LIMIT 500');$s->execute($params);$rows=$s->fetchAll();json_response(['data'=>array_map(fn($l)=>listing_public_payload($l,true),$rows),'meta'=>['count'=>count($rows),'precise_location_access'=>true]]);
